    /// <summary>
    /// Post target process method to change the journal header field
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">Type DefinitionGroupExecution</param>
    public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        
        CustomerPaymentJournalLineSettledInvoiceStaging metStaging, metStagingError;
        LedgerJournalTable                              metLedgerJournalTable;
            
        // Check if processing of all records are completed
        select firstonly RecId
                from metStaging
                where metStaging.DefinitionGroup    == _dmfDefinitionGroupExecution.DefinitionGroup
                    && metStaging.ExecutionId       == _dmfDefinitionGroupExecution.ExecutionId
                    && metStaging.TransferStatus    != DMFTransferStatus::Completed
                    && metStaging.TransferStatus    != DMFTransferStatus::Duplicate
                    && metStaging.TransferStatus    != DMFTransferStatus::Error;
        
        if(!metStaging.RecId)
        {
            try
            {
                while select JournalBatchNumber
                from metStaging
                group by metStaging.JournalBatchNumber
                where metStaging.DefinitionGroup    == _dmfDefinitionGroupExecution.DefinitionGroup
                && metStaging.ExecutionId           == _dmfDefinitionGroupExecution.ExecutionId
                && metStaging.TransferStatus        == DMFTransferStatus::Completed
                {
                    // Approve journal if "ApproveActive" flag on the journal name setup is true
                    // and all records are successfully imported for the journal
                    
                    metLedgerJournalTable   = LedgerJournalTable::find(metStaging.JournalBatchNumber);

                    if(!metLedgerJournalTable.Approver && LedgerJournalName::find(metLedgerJournalTable.JournalName).ApproveActive)
                    {
                        select firstonly RecId
                            from metStagingError
                            where metStagingError.DefinitionGroup    == _dmfDefinitionGroupExecution.DefinitionGroup
                                && metStagingError.ExecutionId       == _dmfDefinitionGroupExecution.ExecutionId
                                && metStagingError.JournalBatchNumber   == metStaging.JournalBatchNumber
                                && metStagingError.TransferStatus    == DMFTransferStatus::Error;
                        
                        if(!metStagingError.RecId)
                        {
                            metLedgerJournalTable.selectForUpdate(true);
                            ttsbegin;
                            metLedgerJournalTable.markReportAsReady();
                            metLedgerJournalTable.markApproved();
                            metLedgerJournalTable.update();
                            ttscommit;
                        }
                    }
                }
            }
            catch (Exception::Deadlock)
            {
                // retry on deadlock
                retry;
            }
            catch (Exception::UpdateConflict)
            {
                // try to resolve update conflict
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
        }
    }
